# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl


@triton.jit
def _dropout_kernel(
    X,
    N,
    thr,
    scale,
    seed,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    step = nprog * BLOCK
    base = pid * BLOCK
    while base < N:
        offs = base + tl.arange(0, BLOCK)
        mask = offs < N
        x = tl.load(X + offs, mask=mask, other=0.0)
        # Vectorized minimal integer hash on the vector pipe: one 32-bit
        # multiply (spreads low->high bits) then one xorshift (folds high->low),
        # which decorrelates the sequential offsets. Fewer ops than lowbias32.
        k = (offs ^ seed).to(tl.uint32)
        k = k * 0x9E3779B1
        k = k ^ (k >> 15)
        # The low 23 bits are a uniform integer in [0, 2**23). Compare directly
        # against thr = int(p * 2**23) in uint32: keep when >= thr, so the drop
        # fraction equals thr/2**23 == p. Avoids the int->float cast, the float
        # multiply, and the float compare entirely (all integer vector ops).
        keep = (k & 0x7FFFFF).to(tl.int32) >= thr
        # Multiply in the operand's native dtype to avoid the fp32 up/down
        # casts on the fp16/bf16 data path (scale <= 10 is representable).
        s = scale.to(x.dtype)
        out = tl.where(keep, x * s, tl.zeros_like(x))
        tl.store(X + offs, out, mask=mask, eviction_policy="evict_first")
        base += step


def _vectorcore_count():
    try:
        import torch_npu  # noqa: F401
        from triton.runtime import driver

        props = driver.active.utils.get_device_properties(torch.npu.current_device())
        n = props.get("num_vectorcore")
        if n:
            return int(n)
    except Exception:
        pass
    return 40


def dropout_(input, p=0.5, train=True):
    # train=False or p==0 is an exact no-op (bit-exact): return input untouched.
    if (not train) or p == 0:
        return input

    N = input.numel()
    if N == 0:
        return input

    scale = 1.0 / (1.0 - float(p))

    # Integer threshold on the low 23 bits: keep when hash23 >= thr, so the
    # drop fraction equals thr/2**23 == p.
    thr = int(float(p) * 8388608.0)

    # Per-call seed read from torch default generator (statistical validation,
    # so exact RNG stream need not match any reference).
    seed = int(torch.randint(0, 2**31 - 1, (1,), device="cpu").item())

    BLOCK = 4096
    n_blocks = triton.cdiv(N, BLOCK)
    # Cap program count: hardware coreDim must be <= 65535, and we want a
    # bounded persistent grid strided by tl.num_programs(0).
    cap = _vectorcore_count()
    grid = (min(n_blocks, cap),)
    _dropout_kernel[grid](input, N, thr, float(scale), seed, BLOCK=BLOCK)
    return input
